diff --git a/Umbraco.Bench.Frontend/src/site.css b/Umbraco.Bench.Frontend/src/site.css
index 9de0c59..e6cbff8 100644
--- a/Umbraco.Bench.Frontend/src/site.css
+++ b/Umbraco.Bench.Frontend/src/site.css
@@ -6,3 +6,59 @@

 /* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
    but content passed into their slots renders in the light DOM and is styled here. */
+
+/* Block grid layout for Umbraco's default grid markup (Views/Partials/blockgrid). */
+.umb-block-grid__layout-container {
+  display: grid;
+  grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
+  gap: 3rem 2rem;
+}
+
+.umb-block-grid__layout-item {
+  grid-column: 1 / -1;
+}
+
+@media (min-width: 768px) {
+  .umb-block-grid__layout-item {
+    grid-column: auto / span min(var(--umb-block-grid--item-column-span, 12), var(--umb-block-grid--grid-columns, 12));
+  }
+}
+
+/* Rich text editor output. */
+@layer components {
+  .rich-text {
+    @apply text-lg leading-relaxed text-slate-700;
+  }
+
+  .rich-text > * + * {
+    @apply mt-5;
+  }
+
+  .rich-text h2 {
+    @apply mt-10 text-3xl font-bold tracking-tight text-slate-900;
+  }
+
+  .rich-text h3 {
+    @apply mt-8 text-2xl font-semibold text-slate-900;
+  }
+
+  .rich-text a {
+    @apply font-medium text-indigo-600 underline hover:text-indigo-800;
+  }
+
+  .rich-text ul {
+    @apply list-disc space-y-2 pl-6;
+  }
+
+  .rich-text ol {
+    @apply list-decimal space-y-2 pl-6;
+  }
+
+  .rich-text code {
+    @apply rounded bg-slate-200 px-1.5 py-0.5 font-mono text-base text-slate-900;
+  }
+
+  .rich-text strong {
+    @apply font-semibold text-slate-900;
+  }
+}
