--- /dev/null
+++ b/Umbraco.Bench.Umbraco/Views/Shared/Components/BlogPostList/Default.cshtml
@@ -0,0 +1,40 @@
+@using System.Globalization
+@model BlogPostListModel
+
+<section>
+    @if (!string.IsNullOrWhiteSpace(Model.Heading))
+    {
+        <h2 class="mb-8 text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
+    }
+    @if (Model.Posts.Count == 0)
+    {
+        <p class="text-slate-500">No posts yet.</p>
+    }
+    else
+    {
+        <div class="grid gap-8 md:grid-cols-2">
+            @foreach (var post in Model.Posts)
+            {
+                <article class="group flex flex-col overflow-hidden rounded-2xl bg-white shadow-md ring-1 ring-slate-200 transition hover:-translate-y-1 hover:shadow-xl">
+                    @if (post.ImageUrl is not null)
+                    {
+                        <a href="@post.Url" class="block aspect-video overflow-hidden">
+                            <img src="@post.ImageUrl" alt="@post.ImageAlt" loading="lazy" class="h-full w-full object-cover transition duration-500 group-hover:scale-105" />
+                        </a>
+                    }
+                    <div class="flex flex-1 flex-col gap-3 p-6">
+                        <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("d MMMM yyyy", CultureInfo.InvariantCulture)</time>
+                        <h3 class="text-xl font-bold text-slate-900">
+                            <a href="@post.Url" class="hover:text-indigo-600">@post.Title</a>
+                        </h3>
+                        @if (!string.IsNullOrWhiteSpace(post.Excerpt))
+                        {
+                            <p class="text-slate-600">@post.Excerpt</p>
+                        }
+                        <a href="@post.Url" class="mt-auto pt-2 font-semibold text-indigo-600 hover:text-indigo-800">Read the post &rarr;</a>
+                    </div>
+                </article>
+            }
+        </div>
+    }
+</section>
diff --git a/Umbraco.Bench.Umbraco/Views/Shared/Components/Hero/Default.cshtml b/Umbraco.Bench.Umbraco/Views/Shared/Components/Hero/Default.cshtml
