@@ -0,0 +1,30 @@
+@model HeroModel
+
+@if (Model.ImageUrl is not null)
+{
+    <section class="relative overflow-hidden rounded-3xl bg-slate-900 text-white shadow-xl">
+        <img src="@Model.ImageUrl" alt="@Model.ImageAlt" class="absolute inset-0 h-full w-full object-cover opacity-60" />
+        <div class="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/40 to-transparent"></div>
+        <div class="relative flex min-h-[26rem] flex-col justify-end gap-4 p-8 md:p-12">
+            <h1 class="max-w-3xl text-4xl font-extrabold tracking-tight md:text-6xl">@Model.Heading</h1>
+            @if (!string.IsNullOrWhiteSpace(Model.Intro))
+            {
+                <p class="max-w-2xl text-lg text-slate-200 md:text-xl">@Model.Intro</p>
+            }
+            @if (!string.IsNullOrWhiteSpace(Model.ImageCredit))
+            {
+                <p class="text-xs text-slate-400">@Model.ImageCredit</p>
+            }
+        </div>
+    </section>
+}
+else
+{
+    <section class="py-12">
+        <h1 class="max-w-3xl text-4xl font-extrabold tracking-tight text-slate-900 md:text-6xl">@Model.Heading</h1>
+        @if (!string.IsNullOrWhiteSpace(Model.Intro))
+        {
+            <p class="mt-4 max-w-2xl text-lg text-slate-600 md:text-xl">@Model.Intro</p>
+        }
+    </section>
+}
