+@inherits UmbracoViewPage
+@{
+    Layout = null;
+    var home = Model.AncestorOrSelf<BlogFrontPage>();
+}
+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <title>@(home is null || home.Id == Model.Id ? Model.Name : $"{Model.Name} | {home.Name}")</title>
+    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
+</head>
+<body class="min-h-screen bg-slate-50 text-slate-800 antialiased">
+    <header class="border-b border-slate-200 bg-white/80 backdrop-blur">
+        <div class="mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
+            <a href="@(home?.Url() ?? "/")" class="text-lg font-extrabold tracking-tight text-slate-900">@(home?.Name ?? "Blog")</a>
+            <span class="text-sm text-slate-500">Built with Umbraco + MCP</span>
+        </div>
+    </header>
+    <main class="mx-auto max-w-6xl px-6 py-10">
+        @RenderBody()
+    </main>
+    <footer class="border-t border-slate-200 py-8 text-center text-sm text-slate-500">
+        Photos from <a href="https://unsplash.com" class="underline hover:text-slate-700">Unsplash</a>.
+    </footer>
+</body>
+</html>

