@@ -0,0 +1,25 @@
+@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
+@{
+    var posts = Umbraco.AssignedContentItem.AncestorOrSelf<BlogFrontPage>()?.Children<BlogPost>()?
+        .OrderByDescending(post => post.PublishDate)
+        .AsEnumerable() ?? [];
+    if (Model.Content.MaxItems > 0)
+    {
+        posts = posts.Take(Model.Content.MaxItems);
+    }
+
+    var model = new BlogPostListModel
+    {
+        Heading = Model.Content.Heading,
+        Posts = posts.Select(post => new BlogPostTeaserModel
+        {
+            Title = post.Name,
+            Url = post.Url(),
+            PublishDate = post.PublishDate,
+            Excerpt = post.Excerpt,
+            ImageUrl = post.TeaserImage?.GetCropUrl(width: 800, height: 450, imageCropMode: ImageCropMode.Crop),
+            ImageAlt = post.TeaserImage?.Name,
+        }).ToList(),
+    };
+}
+@await Component.InvokeAsync("BlogPostList", new { model })
